param([Parameter(Mandatory=$true)][string]$SourceRoot,[Parameter(Mandatory=$true)][string]$Generator)
$ErrorActionPreference='Stop';$root=Join-Path ([IO.Path]::GetTempPath()) ('aevrynd-sl-'+[Guid]::NewGuid().ToString('N'));$sdk=Join-Path $root sdk
$dlls=@('sl.interposer.dll','sl.common.dll','sl.dlss.dll','nvngx_dlss.dll','NvLowLatencyVk.dll');$notices=@('license.txt','3rd-party-licenses.md','bin/x64/nvngx_dlss.license.txt','bin/x64/reflex.license.txt');$required=@($dlls|%{'bin/x64/'+$_})+$notices+@('AEVRYND_REDISTRIBUTION_APPROVED.manifest')
function Hash($path){$s=[IO.File]::OpenRead($path);try{$h=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($h.ComputeHash($s))}finally{$h.Dispose()}}finally{$s.Dispose()}}
function Configure($build){New-Item -ItemType Directory -Force $build|Out-Null;$prior=$ErrorActionPreference;$ErrorActionPreference='Continue';$text=(& cmake -S $SourceRoot -B $build -G $Generator -A x64 "-DSTREAMLINE_ROOT=$sdk" -DAEVRYND_ENABLE_STREAMLINE=ON -DAEVRYND_ENABLE_STREAMLINE_RUNTIME=ON -DAEVRYND_STREAMLINE_PACKAGE_TEST_TARGET=ON 2>&1|Out-String);$exit=$LASTEXITCODE;$ErrorActionPreference=$prior;return ,@($exit,$text)}
try{
 foreach($r in $required){$p=Join-Path $sdk $r;New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;[IO.File]::WriteAllText($p,"fixture:$r")}
 foreach($missing in $required){$p=Join-Path $sdk $missing;Remove-Item $p;$result=Configure (Join-Path $root ('m-'+($missing-replace'[/\\.]','-')));if($result[0]-eq0-or$result[1]-notmatch[regex]::Escape([IO.Path]::GetFileName($missing))){throw "Inexact missing gate: $missing output=$($result[1])"};[IO.File]::WriteAllText($p,"fixture:$missing")}
 $build=Join-Path $root positive;$result=Configure $build;if($result[0]-ne0){throw 'Approved fixture configure failed'};& cmake --build $build --config Release --target AevryndStreamlinePackageFixture -- /m:1 /nr:false /p:UseMultiToolTask=false|Out-Null;if($LASTEXITCODE){throw 'Approved fixture build failed'}
 $bin=Join-Path $build bin/Release;$expectedDlls=@($dlls|Sort-Object);$actual=@(Get-ChildItem $bin -File -Filter '*.dll'|% Name|Sort-Object);if(Compare-Object $expectedDlls $actual){throw 'DLL exact-set mismatch'};$extra=Join-Path $bin 'sl.extra.dll';[IO.File]::WriteAllText($extra,'unexpected');$withExtra=@(Get-ChildItem $bin -File -Filter '*.dll'|% Name|Sort-Object);if(-not(Compare-Object $expectedDlls $withExtra)){throw 'Extra DLL injection was not rejected'};Remove-Item $extra;$lic=Join-Path $bin licenses/streamline;$expected=@($notices|%{[IO.Path]::GetFileName($_)}|Sort-Object);if(Compare-Object $expected @(Get-ChildItem $lic -File|% Name|Sort-Object)){throw 'Notice exact-set mismatch'}
 foreach($r in $notices){if((Hash (Join-Path $sdk $r))-ne(Hash (Join-Path $lic ([IO.Path]::GetFileName($r))))){throw "Notice hash mismatch: $r"}};foreach($n in $dlls){if((Hash (Join-Path $sdk ('bin/x64/'+$n)))-ne(Hash (Join-Path $bin $n))){throw "DLL hash mismatch: $n"}}
 $approval=Join-Path $sdk 'AEVRYND_REDISTRIBUTION_APPROVED.manifest';Remove-Item -LiteralPath $approval;$unapproved=Configure (Join-Path $root unapproved);if($unapproved[0]-eq0-or$unapproved[1]-notmatch'AEVRYND_REDISTRIBUTION_APPROVED.manifest'){throw 'Synthetic complete SDK did not fail closed on unresolved legal approval'}
}finally{if(Test-Path $root){Remove-Item $root -Recurse -Force}}
